static BOOL penName(NSString*n){if(![n isKindOfClass:NSString.class])return NO;NSString*s=[[[n uppercaseString]componentsSeparatedByCharactersInSet:[[NSCharacterSet alphanumericCharacterSet]invertedSet]]componentsJoinedByString:@""];return[s containsString:@"PN7522W"];}
static NSString*dataHex(NSData*d,NSUInteger cap){if(![d isKindOfClass:NSData.class])return @"";const uint8_t*p=d.bytes;NSMutableString*s=[NSMutableString string];for(NSUInteger i=0;i<MIN(d.length,cap);i++)[s appendFormat:@"%02x",p[i]];return s;}
@interface PenApp:NSObject<NSApplicationDelegate,CBCentralManagerDelegate,CBPeripheralDelegate,NSTableViewDataSource,NSTableViewDelegate>
