@implementation PenApp
-(void)log:(NSString*)event detail:(NSDictionary*)detail{NSDictionary*d=@{@"time":[[NSISO8601DateFormatter new]stringFromDate:[NSDate date]],@"event":event,@"detail":detail?:@{}};NSData*j=[NSJSONSerialization dataWithJSONObject:d options:0 error:NULL];if(self.report&&j){NSFileHandle*f=[NSFileHandle fileHandleForWritingAtPath:self.report];[f seekToEndOfFile];[f writeData:j];[f writeData:[@"\n" dataUsingEncoding:NSUTF8StringEncoding]];[f closeFile];}if(self.text){NSString*s=[[NSString alloc]initWithData:j encoding:NSUTF8StringEncoding];[self.text.textStorage appendAttributedString:[[NSAttributedString alloc]initWithString:[s stringByAppendingString:@"\n"]]];[self.text scrollRangeToVisible:NSMakeRange(self.text.string.length,0)];}}
-(NSButton*)button:(NSString*)title x:(CGFloat)x action:(SEL)a{NSButton*b=[NSButton buttonWithTitle:title target:self action:a];b.frame=NSMakeRect(x,420,150,32);[self.window.contentView addSubview:b];return b;}
-(void)applicationDidFinishLaunching:(NSNotification*)n{self.rows=[NSMutableArray array];NSString*dir=[NSHomeDirectory()stringByAppendingPathComponent:@"Library/Logs/LatitudePen"];[[NSFileManager defaultManager]createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:@{NSFilePosixPermissions:@0700} error:NULL];self.report=[dir stringByAppendingPathComponent:[NSString stringWithFormat:@"PN7522W-%.0f.jsonl",[NSDate date].timeIntervalSince1970]];[[NSData data]writeToFile:self.report atomically:YES];self.window=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,800,520) styleMask:NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskMiniaturizable backing:NSBackingStoreBuffered defer:NO];self.window.title=@"Dell PN7522W — Bluetooth LE connection";[self.window center];
 NSTextField*hint=[NSTextField wrappingLabelWithString:@"Hold the pen’s top button for 3 seconds until blue blinks. Start a scan, select Dell PN7522W, then Connect. BLE connection is separate from pressure/inking through the screen digitizer."];hint.frame=NSMakeRect(20,460,760,45);[self.window.contentView addSubview:hint];
 [self button:@"Start LE scan" x:20 action:@selector(scan:)];[self button:@"Connect selected pen" x:180 action:@selector(connect:)];[self button:@"Disconnect" x:340 action:@selector(disconnect:)];[self button:@"Bluetooth settings" x:500 action:@selector(settings:)];
 self.status=[NSTextField labelWithString:@"Ready. Bluetooth access starts only when you click Scan."];self.status.frame=NSMakeRect(20,390,760,24);[self.window.contentView addSubview:self.status];
 NSScrollView*sv=[[NSScrollView alloc]initWithFrame:NSMakeRect(20,220,760,160)];sv.hasVerticalScroller=YES;self.table=[[NSTableView alloc]initWithFrame:sv.bounds];for(NSArray*a in @[@[@"name",@"Device",@420],@[@"signal",@"RSSI",@70],@[@"kind",@"Type",@240]]){NSTableColumn*c=[[NSTableColumn alloc]initWithIdentifier:a[0]];c.title=a[1];c.width=[a[2]doubleValue];[self.table addTableColumn:c];}self.table.dataSource=self;self.table.delegate=self;sv.documentView=self.table;[self.window.contentView addSubview:sv];
 NSScrollView*logs=[[NSScrollView alloc]initWithFrame:NSMakeRect(20,20,760,190)];logs.hasVerticalScroller=YES;self.text=[[NSTextView alloc]initWithFrame:logs.bounds];self.text.editable=NO;self.text.font=[NSFont monospacedSystemFontOfSize:11 weight:NSFontWeightRegular];logs.documentView=self.text;[self.window.contentView addSubview:logs];
 NSMenu*menu=[NSMenu new];NSMenuItem*app=[NSMenuItem new];[menu addItem:app];NSMenu*m=[NSMenu new];[m addItemWithTitle:@"Quit Latitude Pen" action:@selector(terminate:) keyEquivalent:@"q"];app.submenu=m;NSApp.mainMenu=menu;
