-(NSInteger)numberOfRowsInTableView:(NSTableView*)table{return self.rows.count;}
-(id)tableView:(NSTableView*)table objectValueForTableColumn:(NSTableColumn*)column row:(NSInteger)row{if(row<0||(NSUInteger)row>=self.rows.count)return @"";return self.rows[row][column.identifier]?:@"";}
-(void)scan:(id)sender{self.wantScan=YES;self.ads=0;self.penAds=0;[self.rows removeAllObjects];[self.table reloadData];[self.timer invalidate];if(!self.central)self.central=[[CBCentralManager alloc]initWithDelegate:self queue:dispatch_get_main_queue() options:@{CBCentralManagerOptionShowPowerAlertKey:@NO}];else[self centralManagerDidUpdateState:self.central];}
-(void)centralManagerDidUpdateState:(CBCentralManager*)central{[self log:@"central-state" detail:@{@"state":@(central.state),@"authorization":@(CBManager.authorization)}];
 switch(central.state){case CBManagerStatePoweredOn:self.status.stringValue=@"Bluetooth LE is available.";if(self.wantScan){[central scanForPeripheralsWithServices:nil options:@{CBCentralManagerScanOptionAllowDuplicatesKey:@NO}];self.status.stringValue=@"Scanning all LE advertisements for 40 seconds…";self.timer=[NSTimer scheduledTimerWithTimeInterval:40 target:self selector:@selector(scanEnded:) userInfo:nil repeats:NO];}break;
