-(void)scanEnded:(id)sender{[self.central stopScan];self.wantScan=NO;self.status.stringValue=[NSString stringWithFormat:@"Scan finished: %lu LE devices; %lu pen advertisements. %@",(unsigned long)self.rows.count,(unsigned long)self.penAds,self.penAds?@"Select the pen and Connect.":@"No PN7522W advertisement reached this app."];[self log:@"scan-finished" detail:@{@"nearbyLEDevices":@(self.rows.count),@"penAdvertisements":@(self.penAds),@"systemPairingVerified":@NO}];}
-(void)centralManager:(CBCentralManager*)central didDiscoverPeripheral:(CBPeripheral*)peripheral advertisementData:(NSDictionary<NSString*,id>*)advertisementData RSSI:(NSNumber*)RSSI{NSString*name=advertisementData[CBAdvertisementDataLocalNameKey]?:peripheral.name?:@"Unnamed LE device";BOOL pen=penName(name);self.ads++;if(pen)self.penAds++;NSMutableDictionary*row=nil;for(NSMutableDictionary*r in self.rows)if([r[@"id"]isEqual:peripheral.identifier.UUIDString]){row=r;break;}if(!row){row=[NSMutableDictionary dictionary];[self.rows addObject:row];}row[@"id"]=peripheral.identifier.UUIDString;row[@"peripheral"]=peripheral;row[@"name"]=name;row[@"signal"]=RSSI?:@0;row[@"kind"]=pen?@"PN7522W":@"Other LE device (not exported)";row[@"pen"]=@(pen);[self.table reloadData];if(pen){NSMutableArray*ids=[NSMutableArray array];for(CBUUID*u in advertisementData[CBAdvertisementDataServiceUUIDsKey])[ids addObject:u.UUIDString];[self log:@"pen-advertisement" detail:@{@"name":name,@"id":peripheral.identifier.UUIDString,@"RSSI":RSSI?:@0,@"services":ids,@"connectable":advertisementData[CBAdvertisementDataIsConnectable]?:@NO}];}}
-(void)connect:(id)sender{NSInteger row=self.table.selectedRow;if(row<0||(NSUInteger)row>=self.rows.count){self.status.stringValue=@"Select the Dell PN7522W row first.";return;}NSDictionary*r=self.rows[row];if(![r[@"pen"]boolValue]){self.status.stringValue=@"Connection is restricted to a device advertising PN7522W.";return;}if(self.active){self.status.stringValue=@"Disconnect the existing pen session first.";return;}[self.central stopScan];self.wantScan=NO;[self.timer invalidate];self.active=r[@"peripheral"];self.active.delegate=self;self.status.stringValue=@"Connecting to the pen… macOS may request Bluetooth pairing.";[self log:@"connect-request" detail:@{@"name":r[@"name"]}];[self.central connectPeripheral:self.active options:nil];self.connectionTimer=[NSTimer scheduledTimerWithTimeInterval:20 target:self selector:@selector(connectTimeout:) userInfo:nil repeats:NO];}
-(void)connectTimeout:(id)sender{if(self.active&&self.active.state!=CBPeripheralStateConnected){[self.central cancelPeripheralConnection:self.active];self.status.stringValue=@"Connection timed out. The advertisement was seen, but the link did not complete.";[self log:@"connect-timeout" detail:nil];}}
-(void)disconnect:(id)sender{if(self.active)[self.central cancelPeripheralConnection:self.active];}
-(void)settings:(id)sender{[[NSWorkspace sharedWorkspace]openURL:[NSURL URLWithString:@"x-apple.systempreferences:com.apple.BluetoothPreferences"]];}
-(void)centralManager:(CBCentralManager*)central didConnectPeripheral:(CBPeripheral*)peripheral{[self.connectionTimer invalidate];self.status.stringValue=@"LE link connected. Checking exposed pen services…";[self log:@"connected" detail:@{@"systemHIDPairingVerified":@NO}];[peripheral discoverServices:nil];}
-(void)centralManager:(CBCentralManager*)central didFailToConnectPeripheral:(CBPeripheral*)peripheral error:(NSError*)error{[self.connectionTimer invalidate];self.status.stringValue=@"LE connection failed; the error is saved in the pen report.";[self log:@"connection-failed" detail:@{@"error":error.localizedDescription?:@"unknown"}];self.active=nil;}
-(void)centralManager:(CBCentralManager*)central didDisconnectPeripheral:(CBPeripheral*)peripheral error:(NSError*)error{[self.connectionTimer invalidate];[self log:@"disconnected" detail:@{@"error":error.localizedDescription?:@"none"}];self.active=nil;self.status.stringValue=@"Pen disconnected.";}
-(void)peripheral:(CBPeripheral*)peripheral didDiscoverServices:(NSError*)error{if(error){[self log:@"services-error" detail:@{@"error":error.localizedDescription}];return;}NSMutableArray*ids=[NSMutableArray array];for(CBService*s in peripheral.services){[ids addObject:s.UUID.UUIDString];if([@[@"180A",@"180F",@"1812"]containsObject:s.UUID.UUIDString])[peripheral discoverCharacteristics:nil forService:s];}[self log:@"services" detail:@{@"UUIDs":ids}];self.status.stringValue=@"LE connected; exposed battery/device/HID services are being checked. Native HID pairing is separate.";}
-(void)peripheral:(CBPeripheral*)peripheral didDiscoverCharacteristicsForService:(CBService*)service error:(NSError*)error{if(error){[self log:@"characteristics-error" detail:@{@"service":service.UUID.UUIDString,@"error":error.localizedDescription}];return;}for(CBCharacteristic*c in service.characteristics){NSString*u=c.UUID.UUIDString;[self log:@"characteristic" detail:@{@"service":service.UUID.UUIDString,@"UUID":u,@"properties":@(c.properties)}];if([@[@"2A19",@"2A24",@"2A26",@"2A29",@"2A4B",@"2A4D"]containsObject:u]&&(c.properties&CBCharacteristicPropertyRead))[peripheral readValueForCharacteristic:c];if([u isEqual:@"2A4D"]&&(c.properties&(CBCharacteristicPropertyNotify|CBCharacteristicPropertyIndicate)))[peripheral setNotifyValue:YES forCharacteristic:c];}}
-(void)peripheral:(CBPeripheral*)peripheral didUpdateValueForCharacteristic:(CBCharacteristic*)characteristic error:(NSError*)error{if(error){[self log:@"read-error" detail:@{@"UUID":characteristic.UUID.UUIDString,@"error":error.localizedDescription}];return;}NSString*u=characteristic.UUID.UUIDString;NSMutableDictionary*d=[@{@"UUID":u,@"bytes":@(characteristic.value.length),@"hex":dataHex(characteristic.value,512)}mutableCopy];if([u isEqual:@"2A19"]&&characteristic.value.length==1){uint8_t value=*(const uint8_t*)characteristic.value.bytes;if(value<=100){d[@"batteryPercent"]=@(value);self.status.stringValue=[NSString stringWithFormat:@"Pen LE link works; battery %u%%. System HID pairing is not yet verified.",value];}}else if([@[@"2A24",@"2A26",@"2A29"]containsObject:u]){NSString*s=[[NSString alloc]initWithData:characteristic.value encoding:NSUTF8StringEncoding];if(s)d[@"text"]=s;}[self log:@"characteristic-value" detail:d];}
-(void)peripheral:(CBPeripheral*)peripheral didUpdateNotificationStateForCharacteristic:(CBCharacteristic*)characteristic error:(NSError*)error{[self log:@"notification-state" detail:@{@"UUID":characteristic.UUID.UUIDString,@"enabled":@(characteristic.isNotifying),@"error":error.localizedDescription?:@"none"}];}
-(BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication*)sender{return YES;}
-(void)applicationWillTerminate:(NSNotification*)notification{[self.central stopScan];if(self.active)[self.central cancelPeripheralConnection:self.active];[self.timer invalidate];[self.connectionTimer invalidate];[self log:@"quit" detail:nil];}
@end
